+
+export type FrameBoundaryType =
+	| 'unbounded_preceding'
+	| 'preceding'
+	| 'current_row'
+	| 'following'
+	| 'unbounded_following';
+
+export interface FrameBoundary {
+	type: FrameBoundaryType;
+	offset?: number;
+	rank: number;
+	getSQL(): SQL;
+}
+
+export interface Frame {
+	type: 'rows' | 'range';
+	from?: FrameBoundary;
+	to?: FrameBoundary;
+	getSQL(): SQL;
+}
+
+export interface WindowSpec {
+	partitionBy?: SQLWrapper | SQLWrapper[];
+	orderBy?: SQLWrapper | SQLWrapper[];
+	frame?: Frame;
+}
+
+export const unboundedPreceding: FrameBoundary = {
+	type: 'unbounded_preceding',
+	rank: -Infinity,
+	getSQL: () => sql`unbounded preceding`,
+};
+
+export const currentRow: FrameBoundary = {
+	type: 'current_row',
+	rank: 0,
+	getSQL: () => sql`current row`,
+};
+
+export const unboundedFollowing: FrameBoundary = {
+	type: 'unbounded_following',
+	rank: Infinity,
+	getSQL: () => sql`unbounded following`,
+};
+
+export function preceding(offset: number): FrameBoundary {
+	if (typeof offset !== 'number' || !Number.isInteger(offset) || offset < 0) {
+		throw new Error(`preceding requires a non-negative integer argument, received ${offset}`);
+	}
+	return {
+		type: 'preceding',
+		offset,
+		rank: -offset,
+		getSQL: () => sql`${sql.raw(String(offset))} preceding`,
+	};
+}
+
+export function following(offset: number): FrameBoundary {
+	if (typeof offset !== 'number' || !Number.isInteger(offset) || offset < 0) {
+		throw new Error(`following requires a non-negative integer argument, received ${offset}`);
+	}
+	return {
+		type: 'following',
+		offset,
+		rank: offset,
+		getSQL: () => sql`${sql.raw(String(offset))} following`,
+	};
+}
+
+export function rows(spec?: { from?: FrameBoundary; to?: FrameBoundary }): Frame {
+	const from = spec?.from ?? unboundedPreceding;
+	const to = spec?.to;
+
+	if (to !== undefined) {
+		if (from.rank > to.rank) {
+			throw new Error("The 'from' boundary cannot be ordered after the 'to' boundary");
+		}
+		return {
+			type: 'rows',
+			from,
+			to,
+			getSQL: () => sql`rows between ${from.getSQL()} and ${to.getSQL()}`,
+		};
+	}
+
+	if (from.rank > currentRow.rank) {
+		throw new Error("The 'from' boundary cannot be ordered after the 'to' boundary");
+	}
+
+	return {
+		type: 'rows',
+		from,
+		getSQL: () => sql`rows between ${from.getSQL()} and current row`,
+	};
+}
+
+export function range(spec?: { from?: FrameBoundary; to?: FrameBoundary }): Frame {
+	const from = spec?.from ?? unboundedPreceding;
+	const to = spec?.to;
+
+	if (to !== undefined) {
+		if (from.rank > to.rank) {
+			throw new Error("The 'from' boundary cannot be ordered after the 'to' boundary");
+		}
+		return {
+			type: 'range',
+
